window.products.push({"id":760375,"name":"Mark-My-Time 3D Disney Mickey Fractal Digital LED Booklight and Reading Timer - Black","category":"homeandappliances","retail price":16.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/41SE6zUc6HL._AC_.jpg","description":"For a Special Reader—the new Mark-My-Time 3D Disney Digital Book Light with Digital Bookmark and Reading Timer! The new 3D Disney book lights feature a bright 3 LED light on an adjustable arm, an integrated clip to attach the booklight to the pages of your favorite book, and collectible 3D Disney artwork. Choose from Princess Ariel, Buzz Lightyear, Princess Rapunzel, and Princess Belle. All these fun fashion 3D features, plus the homework help timing functions of the original digital bookmark — a cumulative timer that records and stores up to 100 hours, a 60-second fluency timer, and a countdown session timer that alarms when you are finished and even turns off the light. Take the work out of reading homework logs for your child and send them on nightly reading adventures! AGES 5 AND UP | Dimensions: 7-1/2\" x 2\"","images":["https://m.media-amazon.com/images/I/41SE6zUc6HL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Mark-My-Time","source_asin":"B0777SMY8B","category_path":"Home & Kitchen"},"sku":"BM-760375","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0777SMY8B","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0777SMY8B","price_pending":true,"merchant_ready":false});
